function resizePeers() {
    if (!serverConnection)
        return;
    let peers = document.getElementById('peers');
    if(!peers)
        return;
    let tiles = Array.prototype.slice.call(
        peers.querySelectorAll('.peer:not(.peer-hidden)')
    );
    let count = tiles.length;
    let container = document.getElementById('video-container');
    tiles.forEach(function(t) {
        let m = t.querySelector('.media');
        if(m)
            m.style.maxHeight = '';
    });
    if(container && container.classList.contains('peer-focus-mode')) {
        peers.classList.remove('peers-split');
        peers.style.gridTemplateColumns = '';
        peers.style.gridTemplateRows = '';
        return;
    }
    if (!count)
        return;
    let portraits = tiles.filter(function(t) {
        return t.classList.contains('peer-portrait');
    });
    let landscapes = tiles.filter(function(t) {
        return !t.classList.contains('peer-portrait');
    });
    let mobile = isMobileLayout();
    if(portraits.length && landscapes.length && !mobile) {
        peers.classList.add('peers-split');
        peers.style.gridTemplateColumns = '';
        peers.style.gridTemplateRows = '';
        return;
    }
    peers.classList.remove('peers-split');
    let columns;
    if(count <= 1)
        columns = 1;
    else if(count === 2)
        columns = mobile ? 1 : 2;
    else if(count <= 4)
        columns = 2;
    else if(count <= 6)
        columns = mobile ? 2 : 3;
    else if(count <= 9)
        columns = 3;
    else
        columns = Math.ceil(Math.sqrt(count));
    let rows = Math.ceil(count / columns);
    peers.style.gridTemplateColumns = 'repeat(' + columns + ', 1fr)';
    peers.style.gridTemplateRows = 'repeat(' + rows + ', 1fr)';
}

