function logMatchesFilter(e){
 var tipo=(($("log-tipo")&&$("log-tipo").value)||"");
 var nick=((($("log-nick")&&$("log-nick").value)||"").trim().toLowerCase());
 var ip=((($("log-ip")&&$("log-ip").value)||"").trim().toLowerCase());
