 else if(tipo==="temporario"){ if(t!=="temporario") return false; }
 if(nick && String(e.nick||"").toLowerCase().indexOf(nick)<0) return false;
 if(ip && String(e.ip||"").toLowerCase().indexOf(ip)<0) return false;
 return true;
}
